-- El juego de caracteres se fija SIEMPRE: el cliente `mysql` lo toma del entorno y en un
-- contenedor sin locale eso es latin1, que convierte cada tilde en mojibake sin dar error.
SET NAMES utf8mb4;
-- Fotos de puntos de interés (poi-images.js)
UPDATE points_of_interest SET image_url = 'Img/poi/cabo-cope.jpg', source = 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: J.Alberto, CC BY-SA 4.0)' WHERE slug = 'cabo-cope' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cala_blanca_2.JPG', source = 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: Ingegneriadell´elizia, CC BY 3.0)' WHERE slug = 'cala-blanca' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/calabardina.jpg', source = 'Región de Murcia Digital (CARM) - Águilas, Yacimientos; Wikimedia Commons (foto: Rietje Swart, CC BY-SA 2.0). La pedanía queda 554 m FUERA del límite oficial del espacio protegido: entra como puerta de entrada por carretera, que es la función que cumple, y no como un valor de dentro. Distancia medida contra el `parque.geojson` que sirve la app.' WHERE slug = 'calabardina' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Panor%C3%A1mica_de_la_Torre_de_Cope_y_el_Golfo_de_Mazarr%C3%B3n.jpg', source = 'OpenStreetMap contributors (ODbL); tradición oral recogida en fuentes de turismo regional (episodio del incendio pendiente de contrastar con fuente documental primaria); Wikimedia Commons (foto: José Alberto Giménez, CC BY-SA 4.0)' WHERE slug = 'ermita-cope' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Ensenada_de_la_Fuente.jpg', source = 'Wikipedia - "Cabo Cope"; descubriendomurcia.com; tradición oral recogida en fuentes de turismo regional (nombre popular pendiente de confirmar con fuente documental primaria); Wikimedia Commons (foto: Jose Ignacio Martinez Navarro, CC BY-SA 3.0 es)' WHERE slug = 'fuente-piratas' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/lomo-bas.jpg', source = 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 ES)' WHERE slug = 'lomo-bas' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/playa-calnegre.jpg', source = 'OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Mueca, CC BY-SA 4.0)' WHERE slug = 'playa-calnegre' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/puntas-calnegre.jpg', source = 'OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Pau lopezca, CC BY-SA 3.0 ES); Región de Murcia Digital (CARM)' WHERE slug = 'puntas-calnegre' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/torre-cope.jpg', source = 'OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Jose Lorca, dominio público); Región de Murcia Digital (CARM)' WHERE slug = 'torre-cope' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_Cope_-_WLE_Spain_2015.jpg', source = 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM). Posición representativa junto al saladar y la Playa de la Galera; las coordenadas exactas de cada yacimiento no están publicadas. Wikimedia Commons (foto: Raul, CC BY 2.0)' WHERE slug = 'yacimientos-cope-galera' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Playa_de_Calblanque.jpg?width=1280', source = 'Inventario Español de Lugares de Interés Geológico (IELIG, IGME), LIG BEs001 «Playas de Calblanque y Salinas del Rasell», de interés principal geomorfológico e intereses secundarios estratigráfico, tectónico y sedimentológico, consultado de primera mano en el servicio de mapas del IGME. Coordenada tomada del arenal cartografiado en OpenStreetMap (way/130546890), más precisa que el punto único con el que el IELIG representa el LIG entero; Wikimedia Commons (foto: José Miguel Grandal, CC BY-SA 4.0)' WHERE slug = 'playa-de-calblanque' AND park_id = (SELECT id FROM parks WHERE slug = 'calblanque-monte-cenizas-pena-aguila');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Santuario_de_la_Fuensanta%2C_Murcia.JPG?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §1 y Normativa (subzona de uso público intensivo «Santuario de La Fuensanta»); declarado Bien de Interés Cultural el 22.06.1983 según OpenStreetMap y el registro estatal, sin contrastar en la fuente oficial (el registro del Ministerio de Cultura no responde desde este entorno). Coordenada: OpenStreetMap way/55846465 (ODbL); Wikimedia Commons (foto: José Garcia, "pepegar", CC BY-SA 3.0)' WHERE slug = 'santuario-de-la-fuensanta' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Eremitorio_Nuestra_Se%C3%B1ora_de_la_Luz_in_Santo_%C3%81ngel%2C_Murcia%2C_Spain%2C_2020_January_-_2.jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §3.3 (hitos paisajísticos) y §4.3.2. Coordenada: OpenStreetMap way/653754604 (ODbL); Wikimedia Commons (foto: Ximonic (Simo Räsänen), CC BY-SA 4.0)' WHERE slug = 'eremitorio-de-la-luz' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_de_la_Asomada._El_Palmar_(Murcia).jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §1, §3.3 (hito «Cabezo del Puerto») y §4.2.2.1 (monte 79 Bis, Trozo 2.º «Castillo del Puerto»); datación y descripción: Región de Murcia Digital (CARM), ficha del Castillo de la Asomada, que lo cataloga como Bien de Interés Cultural por la Disposición Adicional Segunda de la Ley 16/1985 del Patrimonio Histórico Español. Coordenada: OpenStreetMap node/10277995531, a 13 m de la de Wikidata Q24568061 (ODbL); Wikimedia Commons (foto: Laura Pérez Ibáñez, CC BY-SA 4.0)' WHERE slug = 'castillo-de-la-asomada' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Crestadelgallo.JPG?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §3.3 y §4.2.7.2, y Normativa (subzona de uso público intensivo «Cresta del Gallo»). Coordenada: OpenStreetMap node/747347873 (ODbL); Wikimedia Commons (foto: Gregorico, CC BY-SA 4.0)' WHERE slug = 'cresta-del-gallo' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Paisaje_Lunar_desde_Columbares.jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §3.1.2.3 (Lugares de Interés Geológico: «Bad lands de la vertiente sur de la Sierra de la Cresta del Gallo (Paisaje lunar)», del inventario de El Patrimonio Geológico de la Región de Murcia, Fundación Séneca, 1999), §3.1.2.4 (regosoles margálicos) y §3.3 (hitos paisajísticos). Coordenada aproximada: ninguna fuente delimita el paraje —el PORN solo dice «al sur de la Cresta del Gallo»— y no tiene nodo en OpenStreetMap, así que se le da la del mirador de la Cresta del Gallo, que es el punto desde el que se observa; Wikimedia Commons (foto: Wadim, CC BY-SA 4.0)' WHERE slug = 'paisaje-lunar' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Vistas_desde_el_Pico_Relojero.jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §4.2.7.2 (miradores habilitados: «El Relojero (al pie del Relojero)»). Coordenada aproximada: el plan sitúa el mirador al pie del cerro y la coordenada es la de la torre de observación de la cima, OpenStreetMap way/136894912 (ODbL); Wikimedia Commons (foto: Juan Antonio Pellicer Alcaraz, CC BY-SA 3.0 es)' WHERE slug = 'mirador-del-relojero' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Sierradecarrascoy.JPG?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §3.3 (hitos paisajísticos) y Normativa (zona de conservación prioritaria). Coordenada y altitud: OpenStreetMap node/26864606, que rotula la cumbre con el nombre de la sierra (ODbL); Wikimedia Commons (foto: Sapoproductions, CC BY-SA 4.0)' WHERE slug = 'cumbre-de-carrascoy' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Panel_informativo_en_%C3%81rea_Recreativa_El_Valle_Perdido..jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §4.2.7.2 y Normativa (subzona de uso público intensivo «Valle Perdido-El Sequén»). Coordenada: OpenStreetMap relation/1852332 (ODbL); Wikimedia Commons (foto: Juan Antonio Pellicer Alcaraz, CC BY-SA 3.0 es)' WHERE slug = 'area-recreativa-el-valle-perdido' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Entrada_a_la_Cala_La_Carolina.jpg?width=1280', source = 'Inventario Español de Lugares de Interés Geológico (IELIG), IGME — LIG BE006 «Vulcanismo de La Carolina». La coordenada es la del propio punto del inventario; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'vulcanismo-de-la-carolina' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cala_Cerrada_o_de_los_Cocederos%2C_en_el_Paraje_Protegido_Las_Cuatro_Calas.JPG?width=1280', source = 'Posición: OpenStreetMap way/1459077450 (ODbL). Uso espartero documentado en Wikimedia Commons («Antiguo deposito de esparto en la Cala de los Cocederos», «Depositos excavados en el acantilado, Cala de los Cocederos»); pendiente de contrastar con fuente documental. El IELIG y Commons escriben «Cocederos»; OpenStreetMap, «Cocedores»; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'playa-de-los-cocedores' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cuatro_Calas_Murcia.jpg?width=1280', source = 'Inventario Español de Lugares de Interés Geológico (IELIG), IGME — LIG BE005, cuya denominación oficial es «Playa de Cuatro Calas»; aquí se le da otro nombre para no confundirlo con el del propio espacio protegido. approx: el punto del inventario representa el conjunto del tramo costero, no un afloramiento puntual; Wikimedia Commons (foto: Mynomadicbackpack, CC BY-SA 4.0)' WHERE slug = 'conglomerados-de-cuatro-calas' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Calarreona%2C_lado_sur%2C_en_Las_Cuatro_Calas.JPG?width=1280', source = 'Posición: OpenStreetMap (ODbL). Sendero SL-MU 18 homologado por la FMRM. Su recorrido no aparece dibujado en el mapa: el sendero está señalizado sobre el terreno, pero no cartografiado en OpenStreetMap, que es de donde sale la capa de senderos; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'playa-de-calarreona' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/La_Esparte%C3%B1a_(Isla_Perdiguera).jpg?width=1280', source = 'Plan de gestión integral de los espacios protegidos del Mar Menor y la franja litoral mediterránea de la Región de Murcia (Decreto n.º 259/2019, de 10 de octubre; BORM n.º 242, de 19 de octubre de 2019, suplemento n.º 7), volumen II, §2.1.6.2.7 «Islas del Mar Menor» —que la describe como «la isla más visitada del Mar Menor» y relata la demolición de 2007— y §2.1.3, que caracteriza las islas como «afloramientos volcánicos que destacan como hitos paisajísticos de excepcional interés». El acceso en embarcación con muelle o embarcadero y el «Sendero Natural Isla Perdiguera (Embarcadero – salida túnel)» constan en las Tablas 156 y 157. Coordenada aproximada: centro de la isla cartografiada en OpenStreetMap (way/4787120). Cae 16 m FUERA del límite oficial, dentro del margen de tolerancia con el que se admite un punto representativo de una superficie que sí está dentro; Wikimedia Commons (foto: Juan Antonio de la Puente, CC BY-SA 4.0)' WHERE slug = 'isla-perdiguera' AND park_id = (SELECT id FROM parks WHERE slug = 'espacios-abiertos-e-islas-del-mar-menor');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/CantosVisera2.jpg?width=1280', source = 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.3 «Patrimonio cultural» y §3.2.8 (Tabla 58). La declaración BIC (25.04.1924) y el Decreto n.º 79/1998, de 28 de diciembre, que delimita su entorno de protección (BORM n.º 6 de 09.01.1999), se citan tal y como los recoge el plan: el texto de esas dos normas NO se ha consultado de primera mano. Coordenada de OpenStreetMap (node/2715239120, wikidata Q43082327), que da un solo nodo para los dos abrigos; Wikimedia Commons (foto: Clemens Schmillen, CC BY-SA 4.0)' WHERE slug = 'cantos-de-la-visera' AND park_id = (SELECT id FROM parks WHERE slug = 'monte-arabi');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/InsculturasArabilejo2.jpg?width=1280', source = 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.3 «Patrimonio cultural» y §3.2.8 (Tabla 58, «Grabados rupestres en el Cerro Arabilejo»). La condición de BIC se cita como la recoge el plan; la norma NO se ha consultado de primera mano. Coordenada de OpenStreetMap (node/2715239122, archaeological_site=petroglyph); Wikimedia Commons (foto: Clemens Schmillen, CC BY-SA 4.0)' WHERE slug = 'petroglifos-del-arabilejo' AND park_id = (SELECT id FROM parks WHERE slug = 'monte-arabi');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Molino_de_Quint%C3%ADn%2C_Salinas_de_San_Pedro_del_Pinatar_(6065429806).jpg?width=1280', source = 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §2.3.4 «Patrimonio cultural» (expediente de BIC incoado, tipología de molino salinero de dos tímpanos) y §7.3.4 Tabla 20, unidad 8 «La Mota»; catálogo «Monumentos en la Región de Murcia» de la CARM, ficha 364 «Molinos de Quintín y Calcetera» (Paseo de la Mota), consultado el 2026-08-17 vía datos.gob.es → nexo.carm.es, que aporta la fecha de construcción y el fin del uso. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL), que es quien separa los dos molinos: la ficha de la CARM da UNA sola coordenada para los dos y están a 2,4 km. La traza del PR-MU 65 pasa a 32 m, pero lo que se señala es el molino, no el sendero; Wikimedia Commons (foto: amaianos from Galicia, CC BY 2.0)' WHERE slug = 'molino-de-quintin' AND park_id = (SELECT id FROM parks WHERE slug = 'salinas-arenales-san-pedro-pinatar');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C3%B1os_de_lodo_en_San_Pedro_del_Pinatar.jpg?width=1280', source = 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.4 Tabla 20, unidad 8 «La Mota», que enumera entre sus contenidos «Etnológico: área de baños terapéuticos de lodo», y §7.3.2 Tabla 17, que sitúa un observatorio de aves en la «charca grande de baños de lodo junto a Molino de Quintín». coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: Anidae, CC BY-SA 4.0)' WHERE slug = 'banos-de-lodo' AND park_id = (SELECT id FROM parks WHERE slug = 'salinas-arenales-san-pedro-pinatar');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/ENCA%C3%91IZADA001.jpg?width=1280', source = 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §2.1.4 «Relieve y geomorfología» (Las Encañizadas como «único punto del Mar Menor que de forma natural se abre a la entrada del Mediterráneo» y como zona pseudomareal), §2.3.4 «Patrimonio cultural», que cita el sistema de encañizadas de La Torre y El Ventorrillo entre los elementos de interés cultural recogidos por el PORN, y §7.3.4 Tabla 20, unidad 9. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: Nioger, CC BY 2.5) — la foto retrata el sistema de encañizadas, del que esta gola es una de las dos, y no lleva geoetiqueta: no se puede afirmar que sea ésta y no la del Ventorrillo' WHERE slug = 'gola-de-la-torre' AND park_id = (SELECT id FROM parks WHERE slug = 'salinas-arenales-san-pedro-pinatar');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Playa_de_Punta_de_Algas_-_Salinas_y_Arenales_de_San_Pedro_del_Pinatar%2C_Spain_2024-02-06_(01).jpg?width=1280', source = 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §2.1.4 «Relieve y geomorfología» («como afloramiento del sustrato miocénico, desde Punta de Algas, se extiende paralelamente a la costa una restinga de piedras ahogadas y bajos de arenas conocidos como Punchosos») y §7.3.3 Tabla 18, que la enumera entre los enclaves de costa baja rocosa. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: Ryan Hodnett, CC BY-SA 4.0)' WHERE slug = 'punta-de-algas' AND park_id = (SELECT id FROM parks WHERE slug = 'salinas-arenales-san-pedro-pinatar');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Torrederribada.jpg?width=1280', source = 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.4 Tabla 20, unidad 4 «Playa de la Torre Derribada», que le reconoce contenido geomorfológico (playa), florístico (vegetación psammófila), faunístico (aves limícolas y marinas) e histórico (torre vigía), y §2.1.4, que da la altura de las dunas primarias al norte del puerto. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: No machine-readable author provided. Nioger assumed (based on copyr…, CC BY 2.5) — la foto no lleva geoetiqueta; la sitúa su categoría de Commons, «Playa de la Torre Derribada», que es la de esta playa concreta' WHERE slug = 'playa-de-la-torre-derribada' AND park_id = (SELECT id FROM parks WHERE slug = 'salinas-arenales-san-pedro-pinatar');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Playa_de_La_Llana_-_Salinas_y_Arenales_de_San_Pedro_del_Pinatar%2C_Spain_2024-02-06.jpg?width=1280', source = 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.4 Tabla 20, unidades 6 «Playas de La Llana» (uso didáctico, científico, divulgativo y turístico) y 7 «Arenales de La Llana» (Zona de Conservación Prioritaria), y §2.1.4 para el perfil de playa y duna. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: Ryan Hodnett, CC BY-SA 4.0)' WHERE slug = 'playa-de-la-llana' AND park_id = (SELECT id FROM parks WHERE slug = 'salinas-arenales-san-pedro-pinatar');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/VG_n%C2%BA_87059_La_Capilla.jpg?width=1280', source = 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen II, §3.1.2 «Descripción e interpretación del Paisaje» (cumbre y panorámica) y §1.1.2.2.3 (las especies de los lapiaces de la Cumbre Capilla del Fraile). Coordenada del vértice mapeado en OpenStreetMap (node/8982267849, cota 1.238 m), que coincide en 6 m con el vértice geodésico «La Capilla» de Wikidata (Q115504498); Wikimedia Commons (foto: Caçavertex, CC0)' WHERE slug = 'capilla-del-fraile' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-de-salinas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Pozos_de_la_Nieve_de_Murcia_11-03-2024.jpg?width=1280', source = 'Bien de Interés Cultural, categoría Sitio de Interés Etnográfico (Dirección General de Bienes Culturales, Región de Murcia). Posición de los 28 pozos en OpenStreetMap (man_made=ice_house, ODbL). approx: la coordenada es la del Pozo 1 (node/8543844778) y representa el conjunto; Wikimedia Commons (foto: Lorenzo Soriano, CC BY 4.0)' WHERE slug = 'pozos-de-la-nieve' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Iglesia_de_Santa_Eulalia_de_Merida_(1).jpg?width=1280', source = 'Decreto 96/2002, de 7 de junio, del Consejo de Gobierno de la Región de Murcia, por el que se declara bien de interés cultural, con categoría de monumento, la iglesia de Santa Eulalia de Mérida, en Totana. Posición: OpenStreetMap way/152263929 (ODbL); Wikimedia Commons (foto: Pedro J Pacheco, CC BY-SA 3.0 es)' WHERE slug = 'santuario-de-santa-eulalia' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Antiguo_Sanatorio_de_Tuberculosos_de_Sierra_Espu%C3%B1a_03.jpg?width=1280', source = 'OpenStreetMap way/132482920 (historic=building, building=hospital, ruins=yes, ODbL); denominación confirmada en Nominatim. Fechas de construcción y cierre pendientes de contrastar con fuente documental; Wikimedia Commons (foto: Jayma photography ltd, CC BY-SA 4.0)' WHERE slug = 'sanatorio-de-tuberculosos' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Casa_Forestal_de_Huerta_Espu%C3%B1a._Sierra_Espu%C3%B1a.jpg?width=1280', source = 'OpenStreetMap way/900533315 (historic=yes, ODbL). Pendiente de contrastar con fuente documental; Wikimedia Commons (foto: Lorenzo Soriano, CC BY-SA 4.0)' WHERE slug = 'casa-forestal-de-huerta-espuna' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Centro_de_Visitantes_y_Gesti%C3%B3n_Ricardo_Codorniu._Sierra_Espu%C3%B1a.jpg?width=1280', source = 'OpenStreetMap way/170061146 (amenity=ranger_station, tourism=information, historic=house, ODbL); Wikimedia Commons (foto: Lorenzo Soriano, CC BY-SA 4.0)' WHERE slug = 'centro-de-visitantes-ricardo-codorniu' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Restos_de_la_Torre_del_Azaraque_(Alhama_de_Murcia).jpg?width=1280', source = 'OpenStreetMap way/1097841454 (historic=ruins, man_made=tower, ODbL). Época y función pendientes de contrastar con fuente documental; Wikimedia Commons (foto: Lorenzo Soriano, CC BY-SA 4.0)' WHERE slug = 'torre-del-azaraque' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
